&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;Avoid driving on flooded roads&nbsp;&lt;/span&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
